-- Add specific tropical fruit and yogurt types on existing installations.
-- Existing broad keys retain their meaning and remain assignable fallbacks.
-- Apply before the matching agent/comparison changes; no live data is changed by code deployment.
begin;

update taxonomy_versions set content_hash = '6c2d94d7ab89a9639939ad366d4ca10b0662b5bf16f1efaf4660d70883f62c05' where id = 'c39450a8-ead7-53d3-821f-956df5f5eba5'::uuid;

on conflict (version_id, stable_key) do update set
 parent_id = excluded.parent_id, level = excluded.level, name = excluded.name,
 description = excluded.description, sort_order = excluded.sort_order,
 is_assignable = excluded.is_assignable,
 allowed_transaction_types = excluded.allowed_transaction_types,
 metadata = excluded.metadata, updated_at = now();

on conflict (version_id, ancestor_id, descendant_id) do update set distance = excluded.distance;

delete from taxonomy_synonyms where node_id in ('38d64a6a-cb47-5dff-8871-efd56714b10c'::uuid, '43e2e5cf-25e3-5f2d-8932-0597853c9d81'::uuid, 'c0406763-ad0e-574a-937e-49a850b8c1c5'::uuid, '3c69bc00-841c-5f27-bf0d-d4357f5c46fb'::uuid, '7829ed9b-08d1-5a73-bdae-24e72c26f814'::uuid, 'a6f7865e-d90d-5565-a0b9-0178aad2da0d'::uuid, 'd1f4a543-2803-5b94-9358-819caae0ab83'::uuid, '55ea2ddc-8ab1-5207-b443-62248bc54409'::uuid, '81f1fdcc-c680-5161-84bf-c056f82887ed'::uuid, 'ac9b7844-b0bd-579a-ae22-b0950d3d6c45'::uuid, '79543445-cd54-5706-832d-4c7cefa5cc25'::uuid, 'b25bfbf9-ab5e-5ae0-b2ba-e369b3e32054'::uuid, 'fa27d51c-11e0-5b24-ad3c-1f52995a07b7'::uuid, '0e468873-12cb-5ee0-89ec-0919713007cb'::uuid, 'bb573147-5a56-50cd-9ede-b5558104c026'::uuid, '04c40e82-b0a6-53c7-a306-62d04e6016e0'::uuid, '37ef9f95-de84-53e7-a1a8-f1f03a3d7ad3'::uuid, 'ce61356e-60c1-58e2-91f1-56c158648260'::uuid, '9ab21499-a92c-5337-8c08-bbd50c59888e'::uuid);

on conflict do nothing;

commit;
